internal/bootstrap/anchor.go::SignBootst.text:
func SignBootstrapAnchor(anchor BootstrapAnchor, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (trust.Envelope, error) {
	if anchor.SchemaVersion != BootstrapAnchorSchemaVersion {
		return trust.Envelope{}, fmt.Errorf("%w: new anchors must use schema version %d", ErrBootstrapAnchorInvalid, BootstrapAnchorSchemaVersion)
	}
	if err := anchor.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if len(anchor.LedgerDelegationWire) > 0 {
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return trust.Envelope{}, fmt.Errorf("decode bootstrap ledger delegation: %w", err)
		}
		if err := validateBootstrapAnchorGrantInterval(issuedAt, expiresAt, grantEnvelope); err != nil {
			return trust.Envelope{}, err
		}
	}
	payload, err := trust.EncodePayload(anchor)
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("encode bootstrap anchor: %w", err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return trust.Envelope{}, fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	envelope, err := trust.Sign(payload, bootstrapAnchorScope(anchor.DeploymentID, string(anchor.Cell), anchor.Environment),
		issuedAt, expiresAt, rootPrivateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if envelope.ExpiresAt.Sub(envelope.IssuedAt) > MaxBootstrapAnchorLifetime {
		return trust.Envelope{}, fmt.Errorf("%w: anchor validity exceeds %s", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorLifetime)
	}
	if err := validateBootstrapAnchorEnvelopeSize(envelope); err != nil {
		return trust.Envelope{}, err
	}
	return envelope, nil
}

internal/bootstrap/anchor.go::VerifyBoot.text:
func VerifyBootstrapAnchor(envelope trust.Envelope, roots trust.Keyring, expected BootstrapAnchorExpectation,
	now time.Time, policy trust.Policy,
) (VerifiedBootstrapAnchor, error) {
	return verifyBootstrapAnchor(envelope, roots, expected, now, policy, false, time.Time{})
}

internal/bootstrap/anchor.go::validateBo.text:
func validateBootstrapAnchorGrantInterval(anchorIssuedAt, anchorExpiresAt time.Time, grant trust.Envelope) error {
	if !anchorIssuedAt.Before(anchorExpiresAt) || anchorIssuedAt.Before(grant.IssuedAt) || anchorExpiresAt.After(grant.ExpiresAt) {
		return fmt.Errorf("%w: anchor validity is outside the ledger delegation interval", trust.ErrDelegationTime)
	}
	return nil
}

func validateBootstrapLedgerCapabilitySet(capabilities []trust.Capability, anchor BootstrapAnchor) error {
	wantDomains := BootstrapLedgerCapabilityDomains()
	if len(capabilities) != len(wantDomains) {
		return fmt.Errorf("%w: ledger grant must contain exactly %d capabilities", ErrBootstrapAnchorInvalid, len(wantDomains))
	}
	seen := make(map[string]struct{}, len(capabilities))
	for _, capability := range capabilities {
		if !slices.Contains(wantDomains, capability.Domain) {
			return fmt.Errorf("%w: ledger grant contains an unrecognized capability", ErrBootstrapAnchorInvalid)
		}
		if _, exists := seen[capability.Domain]; exists {
			return fmt.Errorf("%w: ledger grant duplicates a record capability", ErrBootstrapAnchorInvalid)
		}
		seen[capability.Domain] = struct{}{}
		if capability.DeploymentID != anchor.DeploymentID || capability.Cell != string(anchor.Cell) ||
			capability.Environment != anchor.Environment || capability.Role != roleController ||
			!sameStrings(capability.Slots, anchor.ControllerSlots) || !sameStrings(capability.Actions, []string{"sign"}) {
			return fmt.Errorf("%w: ledger grant exceeds or mismatches the anchored slot scope", ErrBootstrapAnchorInvalid)
		}
	}
	for _, domain := range wantDomains {
		if _, exists := seen[domain]; !exists {
			return fmt.Errorf("%w: ledger grant is missing %s capability", ErrBootstrapAnchorInvalid, domain)
		}
	}
	return nil
}

internal/bootstrap/anchor.go::verifyBoot.text:
func verifyBootstrapAnchor(envelope trust.Envelope, roots trust.Keyring, expected BootstrapAnchorExpectation,
	now time.Time, policy trust.Policy, historical bool, acceptedAt time.Time,
) (VerifiedBootstrapAnchor, error) {
	if policy.MaxLifetime <= 0 || policy.MaxLifetime > MaxBootstrapAnchorLifetime || policy.ClockSkew < 0 ||
		envelope.ExpiresAt.Sub(envelope.IssuedAt) > MaxBootstrapAnchorLifetime {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: invalid or overlong anchor verification policy", ErrBootstrapAnchorInvalid)
	}
	if err := validateBootstrapAnchorEnvelopeSize(envelope); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	if err := expected.validate(); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	scope := bootstrapAnchorScope(expected.DeploymentID, string(expected.Cell), expected.Environment)
	var payload []byte
	var err error
	if historical {
		payload, err = trust.VerifyHistorical(envelope, scope, roots, policy)
		if err == nil {
			acceptedAt = acceptedAt.Round(0).UTC()
			if acceptedAt.IsZero() || acceptedAt.Year() < 1 || acceptedAt.Year() > 9999 ||
				acceptedAt.Sub(envelope.IssuedAt) < -policy.ClockSkew || !acceptedAt.Before(envelope.ExpiresAt) {
				err = fmt.Errorf("%w: anchor did not cover accepted installation time", ErrBootstrapAnchorInvalid)
			}
		}
	} else {
		payload, err = trust.VerifyCurrent(envelope, scope, roots, now, policy)
	}
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("verify bootstrap anchor signature: %w", err)
	}
	if len(payload) > MaxBootstrapAnchorBytes {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: anchor exceeds %d bytes", ErrBootstrapAnchorInvalid, MaxBootstrapAnchorBytes)
	}
	var anchor BootstrapAnchor
	if err := protocol.DecodeStrict(payload, &anchor, MaxBootstrapAnchorBytes); err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("decode bootstrap anchor: %w", err)
	}
	if err := anchor.Validate(); err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	if anchor.DeploymentID != expected.DeploymentID || anchor.Environment != expected.Environment || anchor.Cell != expected.Cell {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: anchor does not match fixed local boot identity", ErrBootstrapAnchorInvalid)
	}
	var ledgerDelegation trust.VerifiedDelegation
	if len(anchor.LedgerDelegationWire) > 0 {
		grantEnvelope, err := trust.DecodeEnvelope(anchor.LedgerDelegationWire)
		if err != nil {
			return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: decode ledger delegation wire: %v", ErrBootstrapAnchorInvalid, err)
		}
		if historical {
			ledgerDelegation, err = trust.VerifyDelegationHistorical(grantEnvelope, roots, policy)
		} else {
			ledgerDelegation, err = trust.VerifyDelegationCurrent(grantEnvelope, roots, now, policy)
		}
		if err != nil {
			return VerifiedBootstrapAnchor{}, fmt.Errorf("verify bootstrap ledger delegation: %w", err)
		}
		if err := validateBootstrapAnchorGrantInterval(envelope.IssuedAt, envelope.ExpiresAt, grantEnvelope); err != nil {
			return VerifiedBootstrapAnchor{}, err
		}
		if err := validateVerifiedBootstrapLedgerCapabilities(ledgerDelegation, anchor); err != nil {
			return VerifiedBootstrapAnchor{}, err
		}
	}
	intent, err := canonicalRegionIntent(anchor.InitialRegionIntentWire)
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: %v", ErrBootstrapAnchorInvalid, err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return VerifiedBootstrapAnchor{}, fmt.Errorf("%w: encode verified envelope: %v", ErrBootstrapAnchorInvalid, err)
	}
	digest, err := trust.Fingerprint(envelope)
	if err != nil {
		return VerifiedBootstrapAnchor{}, err
	}
	return VerifiedBootstrapAnchor{
		anchor: cloneBootstrapAnchor(anchor), intent: cloneRegionIntent(intent), ledgerDelegation: ledgerDelegation,
		wire: bytes.Clone(wire), digest: digest, issuedAt: envelope.IssuedAt,
		expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

internal/budget/allowance.go::(Capacity).text:
func (c Capacity) Encode() ([]byte, error) {
	if err := c.Validate(); err != nil {
		return nil, err
	}
	return protocol.EncodeJSON(c)
}

func (c Capacity) Headroom() uint64 {
	if (c.State != StateOK && c.State != StateWarn) || c.ProjectedCents >= c.CapCents {
		return 0
	}
	return c.CapCents - c.ProjectedCents
}

func (c Capacity) Validate() error {
	switch {
	case c.Schema != Schema:
		return fmt.Errorf("capacity schema %d is not %d", c.Schema, Schema)
	case c.At.IsZero():
		return errors.New("capacity at is required")
	case c.Reason == "":
		return errors.New("capacity reason is required")
	case math.IsNaN(c.Ratio) || math.IsInf(c.Ratio, 0) || c.Ratio < 0:
		return errors.New("capacity ratio must be a finite, non-negative number")
	}
	switch c.State {
	case StateNone:
		if c.CapCents != 0 || c.Currency != "" {
			return errors.New("capacity without a budget must not name a cap")
		}
	case StateUnknown, StateOK, StateWarn, StateOver:
		if c.CapCents == 0 || c.CapCents > maxMonthlyCapCents || !currencyCode.MatchString(c.Currency) {
			return errors.New("capacity cap and currency must match a budget")
		}
	default:
		return fmt.Errorf("capacity state %q is unknown", c.State)
	}
	for index, region := range c.Regions {
		switch {
		case region.Cell == "" || index > 0 && c.Regions[index-1].Cell >= region.Cell:
			return errors.New("capacity regions must be sorted by unique cell")
		case region.Nodes < 0 || region.Want < 0:
			return fmt.Errorf("capacity region %q has negative nodes or wants", region.Cell)
		case region.Allowance < region.Nodes || region.Allowance > region.Nodes+1:
			return fmt.Errorf("capacity allowance for %q must be its nodes or one more", region.Cell)
		case region.Allowance > region.Nodes && region.GrantedAt.IsZero(),
			region.Allowance == region.Nodes && !region.GrantedAt.IsZero():
			return fmt.Errorf("capacity grant time for %q must be set exactly when it allows one more node", region.Cell)
		}
	}
	return validateReservations(c)
}

internal/budget/allowance.go::Alerting.text:
func Alerting(open bool, c Capacity) bool {
	switch c.State {
	case StateNone, StateUnknown:
		return open
	}
	if open {
		return c.Ratio >= ClearRatio
	}
	return c.Ratio >= WarnRatio
}

internal/budget/allowance.go::Allocate.text:
func Allocate(budget *Budget, regions []Region, prior *Capacity, now time.Time) Capacity {
	sorted := slices.Clone(regions)
	slices.SortFunc(sorted, func(a, b Region) int { return strings.Compare(a.Cell, b.Cell) })
	capacity := Capacity{Schema: Schema, At: now, Regions: make([]RegionAllowance, len(sorted))}
	if prior != nil {
		capacity.Spending = prior.Spending
		capacity.Reservations = slices.Clone(prior.Reservations)
		capacity.BootstrapReservedCents, capacity.BootstrapSHA256 = prior.BootstrapReservedCents, prior.BootstrapSHA256
	}
	for index, region := range sorted {
		capacity.Regions[index] = RegionAllowance{
			Cell: region.Cell, Nodes: region.Nodes, Want: region.Want, Allowance: region.Nodes, Pressure: region.Pressure,
		}
	}
	if budget == nil {
		capacity.State = StateNone
		capacity.Reason = "no monthly budget is set"
		return capacity
	}
	if err := budget.Validate(); err != nil {
		// Only a valid budget can admit spending, and its cap is never zero.
		capacity.State = StateNone
		capacity.Reason = "the monthly budget is invalid: " + err.Error()
		return capacity
	}
	capacity.CapCents = budget.MonthlyCapCents
	capacity.Currency = budget.Currency

	var projected uint64
	unknown := ""
	for _, region := range sorted {
		// A status from further ahead than clock skew explains is as unknown as a stale one.
		if !region.At.IsZero() && now.Sub(region.At) <= StatusMaxAge && region.At.Sub(now) <= AllowanceMaxAge &&
			region.Currency == budget.Currency {
			projected = saturatingAdd(projected, region.ProjectedCents)
		} else if unknown == "" {
			unknown = region.Cell
		}
	}
	if unknown == "" {
		for index, region := range sorted {
			granted, ok := reservation(prior, region, now)
			if !ok {
				continue
			}
			capacity.Regions[index].Allowance = region.Nodes + 1
			capacity.Regions[index].GrantedAt = granted
			projected = saturatingAdd(projected, region.NodeMonthlyCents)
		}
	}
	if capacity.Spending != nil {
		projected = max(projected, capacity.Spending.ProjectedCents)
	}
	capacity.ProjectedCents = projected
	capacity.Ratio = float64(projected) / float64(budget.MonthlyCapCents)
	switch {
	case unknown != "":
		capacity.State = StateUnknown
		capacity.Reason = fmt.Sprintf("%s has no fresh spend status, so growth is held in every region", unknown)
		return capacity
	case projected >= budget.MonthlyCapCents:
		capacity.State = StateOver
		capacity.Reason = "projected spend is at or over the cap, so growth is held"
		return capacity
	case capacity.Ratio >= WarnRatio:
		capacity.State = StateWarn
	default:
		capacity.State = StateOK
	}

	var candidates []int
	for index, region := range sorted {
		if region.Want > region.Nodes && capacity.Regions[index].Allowance == region.Nodes {
			candidates = append(candidates, index)
		}
	}
	slices.SortFunc(candidates, func(a, b int) int {
		if order := cmp.Compare(sorted[b].Pressure, sorted[a].Pressure); order != 0 {
			return order
		}
		return strings.Compare(sorted[a].Cell, sorted[b].Cell)
	})
	var grants []string
	for _, index := range candidates {
		region := sorted[index]
		next := saturatingAdd(projected, region.NodeMonthlyCents)
		if region.NodeMonthlyCents == 0 || next > budget.MonthlyCapCents {
			continue
		}
		projected = next
		capacity.Regions[index].Allowance++
		capacity.Regions[index].GrantedAt = now
		grants = append(grants, region.Cell+" +1")
	}
	switch {
	case len(grants) > 0:
		capacity.Reason = "granted " + strings.Join(grants, ", ")
	case len(candidates) == 0:
		capacity.Reason = "no region wants more nodes"
	default:
		capacity.Reason = "no more nodes fit under the cap, or their price is unknown"
	}
	capacity.ProjectedCents = projected
	capacity.Ratio = float64(projected) / float64(budget.MonthlyCapCents)
	if projected >= budget.MonthlyCapCents {
		capacity.State = StateOver
	} else if capacity.Ratio >= WarnRatio {
		capacity.State = StateWarn
	}
	return capacity
}

internal/budget/allowance.go::AllowanceF.text:
func AllowanceFor(c Capacity, cell string, now time.Time) (int, bool) {
	if now.Sub(c.At) > AllowanceMaxAge || c.At.Sub(now) > AllowanceMaxAge {
		return 0, false
	}
	index := slices.IndexFunc(c.Regions, func(region RegionAllowance) bool { return region.Cell == cell })
	if index < 0 {
		return 0, false
	}
	return c.Regions[index].Allowance, true
}

internal/budget/allowance.go::DecodeCapa.text:
func DecodeCapacity(payload []byte) (Capacity, error) {
	var c Capacity
	if err := protocol.DecodeStrict(payload, &c, maxDocumentBytes); err != nil {
		return Capacity{}, fmt.Errorf("%w: %w", ErrInvalidCapacity, err)
	}
	if err := c.Validate(); err != nil {
		return Capacity{}, fmt.Errorf("%w: %w", ErrInvalidCapacity, err)
	}
	return c, nil
}

internal/budget/allowance.go::ReadCapaci.text:
func ReadCapacity(ctx context.Context, reader *globalcontrol.Reader) (Capacity, bool, error) {
	document, err := reader.Document(ctx, globalcontrol.KindCapacity, protocol.GlobalScope)
	if errors.Is(err, globalcontrol.ErrNotFound) {
		return Capacity{}, false, nil
	}
	if err != nil {
		return Capacity{}, false, err
	}
	c, err := DecodeCapacity(document.Payload)
	if err != nil {
		return Capacity{}, false, err
	}
	return c, true, nil
}

internal/budget/allowance.go::WriteCapac.text:
func WriteCapacity(ctx context.Context, writer *globalcontrol.Writer, epoch uint64, c Capacity) error {
	if writer == nil {
		return errors.New("capacity requires the home writer")
	}
	for range 8 {
		prior, found, err := ReadCapacity(ctx, &writer.Reader)
		if err != nil {
			return err
		}
		if found {
			c.Spending, c.Reservations = prior.Spending, prior.Reservations
			c.BootstrapReservedCents = max(c.BootstrapReservedCents, prior.BootstrapReservedCents)
			if prior.BootstrapSHA256 != "" {
				c.BootstrapSHA256 = prior.BootstrapSHA256
			}
			if c.Spending != nil && c.State != StateNone {
				c.ProjectedCents = max(c.ProjectedCents, c.Spending.ProjectedCents)
				c.Ratio = float64(c.ProjectedCents) / float64(c.CapCents)
				if c.ProjectedCents >= c.CapCents {
					c.State = StateOver
				} else if c.State == StateOK && c.Ratio >= WarnRatio {
					c.State = StateWarn
				}
			}
		}
		payload, err := c.Encode()
		if err != nil {
			return err
		}
		var expected []byte
		if found {
			expected, err = prior.Encode()
			if err != nil {
				return err
			}
		}
		_, err = writer.PutDocument(ctx, epoch, globalcontrol.KindCapacity, protocol.GlobalScope, payload, func(stored []byte) error {
			if !sameCapacity(stored, expected) {
				return globalcontrol.ErrConflict
			}
			return nil
		})
		if errors.Is(err, globalcontrol.ErrConflict) {
			continue
		}
		return err
	}
	return globalcontrol.ErrConflict
}

internal/budget/allowance.go::reservatio.text:
func reservation(prior *Capacity, region Region, now time.Time) (time.Time, bool) {
	if prior == nil {
		return time.Time{}, false
	}
	index := slices.IndexFunc(prior.Regions, func(granted RegionAllowance) bool { return granted.Cell == region.Cell })
	if index < 0 {
		return time.Time{}, false
	}
	granted := prior.Regions[index]
	if granted.Allowance != region.Nodes+1 || now.Sub(granted.GrantedAt) >= ReservationTTL {
		return time.Time{}, false
	}
	return granted.GrantedAt, true
}

internal/budget/allowance.go::sameCapaci.text:
func sameCapacity(stored, expected []byte) bool {
	if len(stored) == 0 || len(expected) == 0 {
		return bytes.Equal(stored, expected)
	}
	current, err := DecodeCapacity(stored)
	if err != nil {
		return false
	}
	canonical, err := current.Encode()
	return err == nil && bytes.Equal(canonical, expected)
}

internal/budget/allowance.go::saturating.text:
func saturatingAdd(a, b uint64) uint64 {
	if a > math.MaxUint64-b {
		return math.MaxUint64
	}
	return a + b
}

internal/budget/allowance_test.go::TestA.text:
func TestAlertingHysteresisOpensAtWarnAndClosesBelowClear(t *testing.T) {
	at := func(ratio float64) Capacity { return Capacity{State: StateOK, Ratio: ratio} }
	open := Alerting(false, at(0.79))
	if open {
		t.Fatal("alert opened below WarnRatio")
	}
	open = Alerting(open, at(0.8))
	if !open {
		t.Fatal("alert did not open at WarnRatio")
	}
	open = Alerting(open, at(0.77))
	if !open {
		t.Fatal("alert closed above ClearRatio")
	}
	open = Alerting(open, at(0.74))
	if open {
		t.Fatal("alert stayed open below ClearRatio")
	}
	if !Alerting(true, Capacity{State: StateUnknown, Ratio: 0.1}) || Alerting(false, Capacity{State: StateNone, Ratio: 1}) {
		t.Fatal("unknown or unset spend changed the alert")
	}
}

func TestAllocateGrantsByPressureUntilTheCap(t *testing.T) {
	c := Allocate(budgetWithCap(1000), []Region{
		freshRegion("sfo", 1, 2, 0.5, 300, 100),
		freshRegion("gru", 1, 2, 0.9, 300, 100),
		freshRegion("fra", 1, 2, 0.7, 300, 100),
	}, nil, testNow)
	if c.State != StateWarn || c.ProjectedCents != 900 || c.Ratio != 0.9 || c.Headroom() != 100 {
		t.Fatalf("capacity = %+v", c)
	}
	if c.Reason != "granted gru +1, fra +1" {
		t.Fatalf("reason = %q", c.Reason)
	}
	want := map[string]int{"fra": 2, "gru": 2, "sfo": 1}
