func (d demand) levelAt(now time.Time) float64 {
	level := d.base
	for _, step := range d.steps {
		if !now.Before(step.at) {
			level = step.to
		}
	}
	day := 2 * math.Pi * float64(now.Unix()) / (24 * 3600)
	return max(0.2, level+d.swing*math.Sin(day+d.phase))
}

