func (w *Writer) establishTerm(ctx context.Context, epoch uint64) (uint64, error) {
	for range maxAppendAttempts {
		readCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		info, err := w.info(readCtx)
		if err != nil {
			cancel()
			return 0, fmt.Errorf("read global stream sequence: %w", err)
		}
		if err := verifyHome(info.Config, w.replicas); err != nil {
			cancel()
			return 0, err
		}
		current, termSequence, err := readTerm(readCtx, w.stream)
		cancel()
		if err != nil {
			return 0, fmt.Errorf("read global term: %w", err)
		}
		if termSequence > info.State.LastSeq {
			continue
		}
		switch {
		case current == epoch:
			return info.State.LastSeq, nil
		case current > epoch:
			return 0, authority.ErrFenced
		}
		payload, err := protocol.EncodeJSON(term{Epoch: epoch})
		if err != nil {
			return 0, err
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: KindTerm, Key: termKey, Generation: epoch, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		message := nats.NewMsg(subject(KindTerm, termKey))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, publishCancel := context.WithTimeout(ctx, apiTimeout)
		_, err = w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequenceForSubject(termSequence, subject(KindTerm, termKey)),
		)
		publishCancel()
		if err != nil && !wrongLastSequence(err) {
			return 0, fmt.Errorf("publish global term barrier: %w", err)
		}
		// Re-read: our barrier or a concurrent newer one is now current.
	}
	return 0, ErrConflict
}

func (w *Writer) put(ctx context.Context, epoch uint64, kind Kind, key string, generation uint64, payload []byte,
	admit func(prior []byte) error,
) (uint64, error) {
	if epoch == 0 {
		return 0, authority.ErrFenced
	}
	w.mu.Lock()
	defer w.mu.Unlock()
	if err := w.fencer.Guard(ctx, epoch); err != nil {
		return 0, err
	}
	for range maxAppendAttempts {
		lastSequence, err := w.establishTerm(ctx, epoch)
		if err != nil {
			return 0, err
		}
		next := max(generation, 1)
		prior, priorSequence, err := w.read(ctx, kind, key)
		switch {
		case errors.Is(err, ErrNotFound):
		case err != nil:
			return 0, err
		case priorSequence > lastSequence:
			continue
		case (generation == 0 || prior.Generation == generation) && bytes.Equal(prior.Payload, payload):
			// An identical retry after an unknown publish outcome is idempotent.
			return priorSequence, nil
		case generation == 0:
			next = prior.Generation + 1
		case generation <= prior.Generation:
			return 0, ErrStaleRecord
		}
		if epoch < prior.Epoch {
			return 0, authority.ErrFenced
		}
		if admit != nil {
			if err := admit(prior.Payload); err != nil {
				return 0, err
			}
		}
		data, err := protocol.EncodeJSON(record{
			Version: recordVersion, Kind: kind, Key: key, Generation: next, Epoch: epoch, Payload: payload,
		})
		if err != nil {
			return 0, err
		}
		if w.beforePublish != nil {
			w.beforePublish()
		}
		message := nats.NewMsg(subject(kind, key))
		message.Data = data
		message.Header.Set(EpochHeader, strconv.FormatUint(epoch, 10))
		publishCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		ack, err := w.js.PublishMsg(publishCtx, message,
			jetstream.WithExpectStream(StreamName),
			jetstream.WithExpectLastSequence(lastSequence),
			jetstream.WithExpectLastSequenceForSubject(priorSequence, subject(kind, key)),
			jetstream.WithMsgID(string(kind)+"."+key+"."+strconv.FormatUint(next, 10)),
		)
		cancel()
		if wrongLastSequence(err) {
			// Another append won: a newer term barrier or a concurrent write.
			// The next attempt observes it and fences or re-checks the CAS.
			continue
		}
		if err != nil {
			return 0, fmt.Errorf("publish global %s record: %w", kind, err)
		}
		if ack.Duplicate {
			// The message ID was seen; only an identical stored record is success.
			stored, sequence, readErr := w.read(ctx, kind, key)
			if readErr != nil || stored.Generation != next || !bytes.Equal(stored.Payload, payload) {
				return 0, ErrConflict
			}
			return sequence, nil
		}
		return ack.Sequence, nil
	}
	return 0, ErrConflict
}

internal/globalcontrol/store.go::OpenHom.text:
func OpenHome(ctx context.Context, js jetstream.JetStream, cell string, peers []string, replicas int,
	fencer authority.Fencer,
) (*Writer, error) {
	if !cellToken.MatchString(cell) {
		return nil, errors.New("global home cell is invalid")
	}
	if err := validMirrorPeers(cell, peers); err != nil {
		return nil, err
	}
	if fencer == nil || fencer.Current().Scope != protocol.GlobalScope {
		return nil, errors.New("global writes require the global-scope authority")
	}
	stream, err := openStream(ctx, js, HomeStreamConfig(replicas), func(actual jetstream.StreamConfig) error {
		return verifyHome(actual, replicas)
	})
	if err != nil {
		return nil, err
	}
	if err := ensureMirrorConsumers(ctx, stream, peers, replicas); err != nil {
		return nil, err
	}
	if err := removeStaleMirrorConsumers(ctx, stream, peers); err != nil {
		return nil, err
	}
	return &Writer{Reader: Reader{stream: stream, js: js}, home: cell, fencer: fencer, replicas: replicas}, nil
}

internal/globalcontrol/store.go::readTer.text:
func readTerm(ctx context.Context, stream jetstream.Stream) (uint64, uint64, error) {
	message, err := stream.GetLastMsgForSubject(ctx, subject(KindTerm, termKey))
	if errors.Is(err, jetstream.ErrMsgNotFound) {
		return 0, 0, nil
	}
	if err != nil {
		return 0, 0, err
	}
	var stored record
	var barrier term
	if err := protocol.DecodeStrict(message.Data, &stored, maxMessageBytes); err != nil ||
		stored.Version != recordVersion || stored.Kind != KindTerm || stored.Key != termKey ||
		stored.Epoch == 0 || stored.Generation != stored.Epoch || !epochHeaderMatches(message.Header, stored.Epoch) ||
		protocol.DecodeStrict(stored.Payload, &barrier, 1024) != nil || barrier.Epoch != stored.Epoch {
		return 0, 0, ErrRecordCorrupt
	}
	return stored.Epoch, message.Sequence, nil
}

internal/globalcontrol/stream.go::ensure.text:
func ensureMirrorConsumers(ctx context.Context, stream jetstream.Stream, peers []string, replicas int) error {
	for _, peer := range peers {
		config := MirrorConsumerConfig(peer, replicas)
		createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		consumer, err := stream.CreatePushConsumer(createCtx, config)
		cancel()
		if errors.Is(err, jetstream.ErrConsumerExists) {
			lookupCtx, lookupCancel := context.WithTimeout(ctx, apiTimeout)
			consumer, err = stream.PushConsumer(lookupCtx, config.Durable)
			lookupCancel()
		}
		if err != nil {
			return fmt.Errorf("create global mirror consumer for %q: %w", peer, err)
		}
		if err := verifyMirrorConsumer(consumer.CachedInfo().Config, peer, replicas); err != nil {
			return err
		}
	}
	return nil
}

internal/globalcontrol/stream.go::inspec.text:
func inspectStream(ctx context.Context, stream jetstream.Stream, created bool) (*jetstream.StreamInfo, error) {
	window, cancel := context.WithTimeout(ctx, createdStreamConvergence)
	defer cancel()
	for {
		infoCtx, infoCancel := context.WithTimeout(window, apiTimeout)
		info, err := stream.Info(infoCtx)
		infoCancel()
		if err == nil || !created || !errors.Is(err, jetstream.ErrStreamNotFound) {
			return info, err
		}
		select {
		case <-window.Done():
			return nil, err
		case <-time.After(100 * time.Millisecond):
		}
	}
}

internal/globalcontrol/stream.go::openSt.text:
func openStream(ctx context.Context, js jetstream.JetStream, config jetstream.StreamConfig,
	verify func(jetstream.StreamConfig) error,
) (jetstream.Stream, error) {
	if js == nil {
		return nil, errors.New("JetStream is required")
	}
	createCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	stream, err := js.CreateStream(createCtx, config)
	cancel()
	created := err == nil
	if err != nil {
		if !errors.Is(err, jetstream.ErrStreamNameAlreadyInUse) {
			return nil, fmt.Errorf("create global control stream: %w", err)
		}
		lookupCtx, lookupCancel := context.WithTimeout(ctx, apiTimeout)
		stream, err = js.Stream(lookupCtx, StreamName)
		lookupCancel()
		if err != nil {
			return nil, fmt.Errorf("lookup global control stream: %w", err)
		}
	}
	info, err := inspectStream(ctx, stream, created)
	if err != nil {
		return nil, fmt.Errorf("inspect global control stream: %w", err)
	}
	if err := verify(info.Config); err != nil {
		return nil, err
	}
	// A home stream created before relayed documents bounded messages at
	// 64 KiB; the bound is raised in place.
	if limit := info.Config.MaxMsgSize; limit > 0 && limit < config.MaxMsgSize {
		raised := info.Config
		raised.MaxMsgSize = config.MaxMsgSize
		updateCtx, cancel := context.WithTimeout(ctx, apiTimeout)
		stream, err = js.UpdateStream(updateCtx, raised)
		cancel()
		if err != nil {
			return nil, fmt.Errorf("raise the global control message bound: %w", err)
		}
	}
	return stream, nil
}

internal/globalcontrol/stream.go::remove.text:
func removeStaleMirrorConsumers(ctx context.Context, stream jetstream.Stream, peers []string) error {
	keep := make(map[string]bool, len(peers))
	for _, peer := range peers {
		keep[protocol.GlobalMirrorConsumer(peer)] = true
	}
	listCtx, cancel := context.WithTimeout(ctx, apiTimeout)
	lister := stream.ConsumerNames(listCtx)
	var stale []string
	for name := range lister.Name() {
		if strings.HasPrefix(name, mirrorConsumerPrefix) && !keep[name] {
			stale = append(stale, name)
		}
	}
	err := lister.Err()
	cancel()
	if err != nil {
		return fmt.Errorf("list global mirror consumers: %w", err)
	}
	for _, name := range stale {
		deleteCtx, deleteCancel := context.WithTimeout(ctx, apiTimeout)
		err := stream.DeleteConsumer(deleteCtx, name)
		deleteCancel()
		if err != nil && !errors.Is(err, jetstream.ErrConsumerNotFound) {
			return fmt.Errorf("delete stale global mirror consumer %q: %w", name, err)
		}
	}
	return nil
}

internal/globalcontrol/stream.go::verify.text:
func verifyHome(actual jetstream.StreamConfig, replicas int) error {
	if actual.Name != StreamName || !slices.Equal(actual.Subjects, []string{protocol.GlobalStateStreamSubject()}) ||
		actual.Mirror != nil || len(actual.Sources) != 0 || actual.Replicas != replicas ||
		// A transform would store records outside the subjects reads use.
		actual.SubjectTransform != nil ||
		actual.Storage != jetstream.FileStorage || actual.Retention != jetstream.LimitsPolicy ||
		!actual.DenyDelete || !actual.DenyPurge || actual.AllowDirect || actual.AllowRollup ||
		actual.MaxMsgs != -1 || actual.MaxBytes != -1 || actual.MaxMsgsPerSubject != -1 || actual.MaxAge != 0 ||
		actual.Metadata["terrascale-contract"] != contract || actual.Metadata["terrascale-role"] != "home" {
		return errors.New("global control stream is not the durable leader-read home stream")
	}
	return nil
}

internal/hostload/report.go::(Report).Va.text:
func (r Report) Validate() error {
	if r.SchemaVersion != SchemaVersion {
		return fmt.Errorf("%w: schema version %d", ErrInvalidReport, r.SchemaVersion)
	}
	if r.Host.CPUCores < 0 || r.Host.CPUCores > MaxCPUCores || r.Host.MemoryBytes > MaxMemoryBytes {
		return fmt.Errorf("%w: host capacity out of range", ErrInvalidReport)
	}
	for _, value := range []*float64{r.Host.CPU, r.Host.Memory, r.Host.Disk} {
		if value != nil && !fraction(*value) {
			return fmt.Errorf("%w: host utilization out of range", ErrInvalidReport)
		}
	}
	for _, value := range []*float64{r.Host.NetworkRxBps, r.Host.NetworkTxBps} {
		if value != nil && !finiteWithin(*value, MaxNetworkBps) {
			return fmt.Errorf("%w: host network rate out of range", ErrInvalidReport)
		}
	}
	if r.Host.Load1 != nil && !finiteWithin(*r.Host.Load1, MaxLoad1) {
		return fmt.Errorf("%w: host load out of range", ErrInvalidReport)
	}
	if len(r.Host.Filesystems) > MaxFilesystems {
		return fmt.Errorf("%w: more than %d filesystems", ErrInvalidReport, MaxFilesystems)
	}
	filesystems := make(map[string]bool, len(r.Host.Filesystems))
	for _, filesystem := range r.Host.Filesystems {
		if !validFilesystem(filesystem) || filesystems[filesystem.Role] {
			return fmt.Errorf("%w: invalid or repeated filesystem role %q", ErrInvalidReport, filesystem.Role)
		}
		filesystems[filesystem.Role] = true
	}
	if len(r.Roles) > MaxRoles {
		return fmt.Errorf("%w: more than %d roles", ErrInvalidReport, MaxRoles)
	}
	seen := make(map[string]struct{}, len(r.Roles))
	for _, role := range r.Roles {
		if !roleRE.MatchString(role.Role) {
			return fmt.Errorf("%w: role token", ErrInvalidReport)
		}
		if _, repeated := seen[role.Role]; repeated {
			return fmt.Errorf("%w: repeated role %q", ErrInvalidReport, role.Role)
		}
		seen[role.Role] = struct{}{}
		if role.CPUCores != nil && !finiteWithin(*role.CPUCores, MaxCPUCores) {
			return fmt.Errorf("%w: role %q CPU out of range", ErrInvalidReport, role.Role)
		}
		if role.MemoryBytes != nil && *role.MemoryBytes > MaxMemoryBytes {
			return fmt.Errorf("%w: role %q memory out of range", ErrInvalidReport, role.Role)
		}
		if role.CPULimit != nil && (!finiteWithin(*role.CPULimit, MaxCPUCores) || *role.CPULimit == 0) ||
			role.MemoryLimit != nil && *role.MemoryLimit > MaxMemoryBytes {
			return fmt.Errorf("%w: role limit out of range", ErrInvalidReport)
		}
		if role.TerraBase != nil {
			if err := role.TerraBase.Validate(); err != nil {
				return fmt.Errorf("%w: role %q: %v", ErrInvalidReport, role.Role, err)
			}
		}
		if role.WAN != nil {
			if role.Role != terrabase.Role {
				return fmt.Errorf("%w: WAN observations require the terrabase role", ErrInvalidReport)
			}
			if err := role.WAN.Validate(); err != nil {
				return fmt.Errorf("%w: role %q WAN: %v", ErrInvalidReport, role.Role, err)
			}
		}
	}
	return nil
}

