func L(pairs ...string) []Label {
	labels := make([]Label, 0, len(pairs)/2)
	for index := 0; index+1 < len(pairs); index += 2 {
		labels = append(labels, Label{Name: pairs[index], Value: pairs[index+1]})
	}
	return labels
}

