func oldest(clocks map[string]time.Time) []string {
	cells := slices.Collect(maps.Keys(clocks))
	slices.SortFunc(cells, func(a, b string) int {
		if order := clocks[a].Compare(clocks[b]); order != 0 {
			return order
		}
		return strings.Compare(a, b)
	})
	return cells
}

