func TestAuthenticatedAPIAndRegionalClient(t *testing.T) {
	s, from, to := fixture(t)
	token := strings.Repeat("a", 32)
	server, err := observability.NewTokenServer(observability.Config{ListenAddress: "127.0.0.1:9463"}, token, observability.ServerDeps{Registry: observability.NewRegistry(false), Health: new(observability.Health)})
	if err != nil {
		t.Fatal(err)
	}
	server.HandleAuthenticated("GET /v1/usage", s.Handler(func(context.Context, time.Time, time.Time) ([]hostload.UsageInterval, error) {
		return fullWindowInventory(from, to, "production", "a", "b", "a/terrabase", "b/terrabase"), nil
	}))
	httpServer := httptest.NewServer(server)
	defer httpServer.Close()
	response, err := http.Get(httpServer.URL + "/v1/usage")
	if err != nil {
		t.Fatal(err)
	}
	response.Body.Close()
	if response.StatusCode != 401 {
		t.Fatalf("unauthenticated status %d", response.StatusCode)
	}
	result, err := (Client{URLs: []string{httpServer.URL}, Token: token}).Query(t.Context(), "gru", from, to)
	if err != nil || !result.Complete {
		t.Fatalf("authenticated query: %+v %v", result, err)
	}
	var encoded bytes.Buffer
	if err := json.NewEncoder(&encoded).Encode(result); err != nil {
		t.Fatal(err)
	}
	if strings.Contains(encoded.String(), token) {
		t.Fatal("token leaked in usage")
	}
	if _, err := (Client{URLs: []string{httpServer.URL}, Token: token}).Query(t.Context(), "sfo", from, to); err == nil {
		t.Fatal("accepted mismatched region")
	}
}

client_query.text:
func (c Client) Query(ctx context.Context, region string, from, to time.Time) (Usage, error) {
	if err := ValidateWindow(region, from, to, time.Now()); err != nil {
		return Usage{}, err
	}
	if len(c.Token) < 32 || len(c.Token) > 4096 || strings.ContainsAny(c.Token, "\r\n") {
		return Usage{}, errors.New("usage requires a valid bearer token")
	}
	hc := http.Client{Timeout: 15 * time.Second}
	if c.HTTP != nil {
		hc = *c.HTTP
	} else {
		transport := &http.Transport{Proxy: nil, IdleConnTimeout: 30 * time.Second}
		defer transport.CloseIdleConnections()
		hc.Transport = transport
	}
	hc.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	ctx, cancel := context.WithCancel(ctx)
	var pending sync.WaitGroup
	defer func() { cancel(); pending.Wait() }()
	requests := make([]*http.Request, 0, len(c.URLs))
	for _, base := range c.URLs {
		u, err := url.Parse(base)
		if err != nil || u.User != nil || u.RawQuery != "" || u.Fragment != "" || u.Host == "" || (u.Scheme != "https" && u.Scheme != "http") {
			return Usage{}, errors.New("invalid usage URL")
		}
		if u.Scheme == "http" && u.Hostname() != "localhost" && u.Hostname() != "127.0.0.1" && !strings.HasSuffix(u.Hostname(), ".nb.ts.internal") {
			return Usage{}, errors.New("HTTP usage URL must use loopback or the encrypted NetBird overlay")
		}
		u.Path = strings.TrimRight(u.Path, "/") + "/v1/usage"
		u.RawQuery = url.Values{"region": {region}, "from": {from.UTC().Format(time.RFC3339Nano)}, "to": {to.UTC().Format(time.RFC3339Nano)}}.Encode()
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
		if err != nil {
			return Usage{}, err
		}
		req.Header.Set("Authorization", "Bearer "+c.Token)
		requests = append(requests, req)
	}
	results := make(chan *Usage, len(requests))
	for _, req := range requests {
		pending.Go(func() {
			var result *Usage
			defer func() { results <- result }()
			response, err := hc.Do(req)
			if err != nil {
				return
			}
			defer response.Body.Close()
			var usage Usage
			err = json.NewDecoder(io.LimitReader(response.Body, 8<<20)).Decode(&usage)
			if response.StatusCode == 200 && err == nil && usage.Region == region && usage.From.Equal(from) && usage.To.Equal(to) {
				result = &usage
			}
		})
	}
	var best *Usage
	for range requests {
		var result *Usage
		select {
		case <-ctx.Done():
			return Usage{}, ctx.Err()
		case result = <-results:
		}
		if err := ctx.Err(); err != nil {
			return Usage{}, err
		}
		if result == nil {
			continue
		}
		if result.Complete {
			return *result, nil
		}
		if best == nil || len(result.Replicas) > len(best.Replicas) {
			best = result
		}
	}
	if err := ctx.Err(); err != nil {
		return Usage{}, err
	}
	if best != nil {
		return *best, nil
	}
	return Usage{}, errors.New("no regional controller returned usage; check Vault token, connectivity and binary version")
}

